using System;
using System.Reflection;
using UnityEngine;
namespace CatCafePreview.Editor
{
    public static class PythonEventReviewVerification
    {
        static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
        public static void BuildAndVerify()
        {
            PythonEventLayout.BuildAndVerify();PythonEventGroupsVerification.BuildAndVerify();PythonEventReviewLayout.Build();
            var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",flags).SetValue(client,preview);var pending=typeof(PythonStateClient).GetField("pending",flags);
            var state=PythonServiceSetup.Sample();state.instance_id="event-review";state.can_set_shifts=true;state.required_action="支援と受け入れに回答してください。";
            state.store_event=new PythonStoreEvent{kind="support",title="保護団体への支援",day=1,funds=1000,choices=new[]{new PythonEventChoice{choice="full",label="支援する",detail="資金1200を使い、閉店時に人気を増やします。",reason="資金が足りません。",can_select=false},new PythonEventChoice{choice="small",label="少額支援する",detail="資金50を使い、閉店時に人気を増やします。",can_select=true},new PythonEventChoice{choice="decline",label="見送る",detail="資金と人気は変化しません。",can_select=true}}};
            state.intake_request=new PythonIntakeState{cat_id="cat-mike",name="ミケ",status="waiting",day=1,cost=100,can_decline=true,accept_reason="飼育スペースが足りません。"};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",flags).Invoke(client,new object[]{state});apply();var list=preview.GetComponent<PythonEventListPanel>();list.Open();Check(list.PendingCount==2 && list.entries[2].GetComponentInChildren<UnityEngine.UI.Text>().text.Contains("回答待ち"),"Waiting labels missing");Capture(preview,"EventReviewList");
            list.Store();var store=preview.GetComponent<PythonStoreEventPanel>();Check(store.choiceDetails[0].text.Contains("効果・費用") && store.choiceDetails[0].text.StartsWith("選べない理由") && !store.choices[0].interactable,"Choice explanation missing");Capture(preview,"EventReviewChoices");store.First();Check(pending.GetValue(client)==null,"Blocked choice sent");store.Second();var command=(PythonShiftCommand)pending.GetValue(client);Check(command!=null && !store.choices[1].interactable && store.notice.text.Contains("送信"),"Busy choice guard");string request=command.request_id;store.Second();Check(((PythonShiftCommand)pending.GetValue(client)).request_id==request,"Duplicate response");pending.SetValue(client,null);state.store_event=null;state.revision++;apply();Check(list.panel.activeSelf && list.PendingCount==1 && list.notice.text.Contains("残り 1件"),"Resolved return feedback");
            list.Intake();string unchanged=JsonUtility.ToJson(state);list.detailClose[1].onClick.Invoke();Check(list.panel.activeSelf && JsonUtility.ToJson(state)==unchanged,"Back answered request");
            state.intake_request.status="declined";state.required_action="";apply();list.SelectGroup(3);Check(list.entries[1].interactable && list.entries[1].GetComponentInChildren<UnityEngine.UI.Text>().text.Contains("記録・閲覧"),"Resolved intake unavailable");list.Intake();var record=preview.GetComponent<PythonEventRecordPanel>();Check(record.panel.activeSelf && record.details.text.Contains("見送り済み") && !record.cat.gameObject.activeSelf,"Declined record");unchanged=JsonUtility.ToJson(state);Capture(preview,"EventReviewRecord");record.Back();Check(list.panel.activeSelf && list.SelectedGroup==3 && pending.GetValue(client)==null && JsonUtility.ToJson(state)==unchanged,"Record back mutated state");
            state.intake_request.status="accepted";apply();preview.GetComponent<PythonPreparationPanel>().Open();list.Intake();Check(record.cat.interactable && record.details.text.Contains("受け入れ済み"),"Accepted record");record.Cat();Check(preview.GetComponent<PythonCatDetailsPanel>().panel.activeSelf,"Accepted cat detail");preview.GetComponent<PythonCatDetailsPanel>().Close();record.Business();Check(!record.panel.activeSelf && !list.panel.activeSelf && !preview.GetComponent<PythonPreparationPanel>().panel.activeSelf,"Business return");
            state.intake_request=null;state.growth_choices=new[]{new PythonGrowthChoice{cat_id="cat-mike",name="ミケ",kind="resolve_growth_type_mastery",title="個別の交流",choices=new[]{new PythonEventChoice{choice="voice",label="声をかける",detail="習得済みです。",reason="すでに習得しています。",can_select=false},new PythonEventChoice{choice="presence",label="静かにそばにいる",detail="静かな交流を強化します。",can_select=true},new PythonEventChoice{choice="gaze",label="目を合わせる",detail="働きかけを強化します。",can_select=true},new PythonEventChoice{choice="rest",label="一緒に休む",detail="働きかけを強化します。",can_select=true}}}};state.required_action="成長を選んでください。";apply();var growth=preview.GetComponent<PythonGrowthPanel>();Check(growth.choices[2].GetComponent<RectTransform>().anchoredPosition.x!=growth.choices[3].GetComponent<RectTransform>().anchoredPosition.x,"Four choices not in grid");Capture(preview,"EventReviewGrowth");
            state.growth_choices[0].choices[1].detail=new string('猫',4000);apply();Canvas.ForceUpdateCanvases();var scroll=growth.choiceDetails[1].GetComponentInParent<UnityEngine.UI.ScrollRect>();Check(scroll.content.rect.height>scroll.viewport.rect.height,"Long choice cannot scroll");
            typeof(PythonStateClient).GetField("online",flags).SetValue(client,false);preview.PythonConnectionError("test");Check(!growth.choices[1].interactable && growth.notice.text.Contains("未接続"),"Offline choice");
            state.growth_choices=null;state.required_action="";state.intake_request=new PythonIntakeState{cat_id="cat-mike",name="ミケ",status="accepted"};apply();list.Open();list.SelectGroup(3);list.Intake();state.instance_id="loaded";apply();Check(!record.panel.activeSelf,"Loaded stale record");Check(pending.GetValue(client)==null,"Viewing sent command");
            Debug.Log("CAT_CAFE_EVENT_REVIEW_VERIFIED: existing layout and groups / waiting labels / effects and costs / reasons / disabled choices / busy / duplicate guard / response return / unresolved back / accepted and declined records / cat details / record back / business return / four choices / long text / offline / loaded state");
        }
        static void Capture(ContentPreview preview,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{preview,"Logs/"+name+".png"});}
    }
}
